INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1126889-ce101', 'stk-me_i10', 'CE 101', 'info', '{"desc": "كورس على برنامج الاوتو كاد\nلاب مدته اربع ساعات وما فيه لكتشر\n\nاعتقد ما ياخذه الا طلاب الهندسة الصناعية\n\nالمادة سهلة اذا كنت متقبل الاوتو كاد في الاوريا\nولو يكون معك شخص او اثنين في السكشن فاهمين وتحلون الهوموركات وتفهمونها مع بعض فالقريد راح يكون في اليد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-101-engineering-graphics/120665/4", "user": "ME_I10", "ts": 1354259059000, "tid": 120665, "pn": 4}}', 1354259059000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466722-ce101', 'stk-mkd', 'CE 101', 'info', '{"desc": "161\nكورس تاخذ فيه أساسيات الـ Autocad زي اللي بالاوريا بس أصعب حبتين\nلو كنت تحبه بالاوريا غالبا بتستمتع فيه\nدكتورين ينزلونه : بيق وبوشامة\nالأول ما أدري عنه لكن سمعت إن مياجره أصعب بشكل عام و شرحه جيّد على كلام اللي ينزلون معه\nبوشامة كويس من ناحية قريدات لكن شرح لأ ، كنت معه وكنت أفهم بشكل محدود", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-101-engineering-graphics/120665/7", "user": "MKD", "ts": 1485019180000, "tid": 120665, "pn": 7}}', 1485019180000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509263-ce101', 'stk-feras-mtn', 'CE 101', 'info', '{"desc": "CE 101 -Term 182\n\nقريدي A+ خذيتها مع Baig\nباختصار مادة تعتمد على تخيلاتك وكيف تقدر تتخيل رسمة 2d وهي على صورة 3d عن طريق autocad … مادة ممتعة كانت بالنسبة لي لكن يمكن ماتمشي معك وترى شوي غثيثة لانه كل اسبوع هوم وورك … ماشفت احد خذا فيها اقل من C الا واحد من اربعة سكاشن خذا D بس حرام ماتجيب فوق B في ذي المادة … المادة ستاندرد والA+ صارت من 90 لكن لا تستهلها لانه من كل سكشن تقريبا ٢-٣ بس خذو A+\n\nالمادة اختصرلك هيا اذا تدور A+ مافي كتاب ولا سلايدات ولا مرجع تذاكر منه الا حاجتين Class Works و Homeworks\nاول ساعة الى ساعة ونص في اللاب تحتاج تركز الدكتور بيشرح وبعدها تطبق بنفسك اللي شفته، التطبيق سهل لكن مثل ماقلت تخيلك للشكل النهائي يصعب من شخص لشخص فمع التدريب بتتحسن، في اول لاب ولا لابين بتحس انه المادة معقدة لانه شي جديد بس بيطلع تافه في النهاية … فركز ثم ركز ثم ركز للشرح ولا تنقل ثم لا تنقل ثم لا تنقل الهوم وورك وانا اضمنلك قريدك A+\n\nباذكر طريقة فهمي ومذاكرتي للمادة ومذاكرة زميلي في نفس اللاب وكلنا جبنا نفس القريد بس اختلفنا في الطريقة:\nخويي كان يركز ويفهم في اللاب ويرجع الغرفة ويحل الهوموورك بنفس اليوم ويدخل الميجر والفاينل بدون مذاكرة او شي لكن ماشاءالله الولد خياله واسع ويفهم ويستوعب من اول مرة\nعلى عكسي انا كنت افهم اللاب واحل الهوم وورك قبل اللاب الاسبوع اللي بعده بيوم فكنت انسى حاجات واطول واتدرب واخش يوتيوب لين احلها بس ارجع احلها من جديد مرة ومرتين لانه كنت احتاج تدريب اكثر ووقت المياجر والفاينل كنت اقضي يوم ليومين قبلها اجلس اطبق كل اللي سويته من HWوCW\n\nفالمادة تفهم الكلاس وورك وترجع بيتك وتحل homework وفيه فيديوهات ممكن تساعدك باليوتيوب اذا كتبت CE 101 kfupm baig بيطلعلك تسجيلات طالب ترم 172 اتوقع ماقصر سجل فيديوهات لشرح لاب Baig ساعة الى ساعة ونص بس الحصص اللي سجلها اغلبها من الاسبوع الثامن وانتا طالع وهي كم موضوع من الميجر الثاني واغلب مواضيع الفاينل (مو كاملة لكن اذا فيه احد فيكم بدأ يسجل الكلاس كامل فيديو من اول اسبوع الى اخر اسبوع او الفيديوهات الناقصة ورفعها يوتيوب حيفيد نفسه لانه بيكون له مرجع وبيفيد غيره مستقبلا وكان ودي اسويها لكن ما استوعبت للاسف الا في نهاية الاسابيع)\n\nوفالكم A+ وبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-101-engineering-graphics/120665/8", "user": "Feras-MTN", "ts": 1556750228000, "tid": 120665, "pn": 8}}', 1556750228000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p539733-ce101', 'stk-s_ssoko', 'CE 101', 'info', '{"desc": "مادة لا تدخلها إلا إذا سحبت لك واحد من أخوياك وخليته يسجل معاك 😆\n\nمادة عبارة عن رسم أوتوكاد\n\nأدري فيه ناس بتقول الأوتوكاد سهل وفلة لكن صدقني راح تكره الأوتوكاد بعد هالكورس\n\nوأتوكاد الأوريا يختلف عن هذا\n\nالعيب مو في الدكاترة العيب في المادة الغبية\n\nأذكر بغيت أسوي دروب وأنا قاعد في الكلاس من الطفش 😆\n\nأنا كنت عند المانع ، بصراحة الدكتور أخلاقه عالية جدًا وشرحه ممتاز\n\nبس بالدرجات حقاني ويعطيك حقك بدون لا زيادة ولا نقصان\n\nصح إنه كرفنا بفاينل يحبه قلبك 😆\n\nولكن الحمد لله إني افتكيت من هالكورس الغبي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce101/83325/9", "user": "S_SsOkO", "ts": 1265585150000, "tid": 83325, "pn": 9}}', 1265585150000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p553693-ce101', 'stk-_1002', 'CE 101', 'info', '{"desc": "الكورس بالنسبة لي كان مره ممتع\nاول واخر كورس استمتع فيه في الجامعه\n\nوفي واحد من الشباب يقول انه لحسه\nمع انه اخذ عند المانع مثلي\n\nوجهات نظر لكن نصيحتي انت سو كل شي بنفسك واذا ما فهمت شي اسأل الدكتور لان كل اسبوع بتآخذ شي جديد وبتطبق عليه في نفس المحاضرة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-101/83848/9", "user": "_1002", "ts": 1267377453000, "tid": 83848, "pn": 9}}', 1267377453000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p692908-ce101', 'stk-es_engineer', 'CE 101', 'info', '{"desc": "انا اخذت مع المانع\n\nالمانع افضل من ابو شامة … مره وحده يشرح لك تفهم علييه علطوول وهو افضل واحد متمكن من المادة\n\nواذا تعودت على شغل الدكتور في اللاب يصير الاختبار سهل عليك\n\nابو شامة ايضا يجي في المرتبة الثانية بعد المانع\n\nلكن غير هذولي الاثنين لا تنزل المادة ابد\n\nخاصة فيه واحد اسمه سنان مدري ايش انتبه منه !!!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce101/94106/2", "user": "ES_Engineer", "ts": 1283063753000, "tid": 94106, "pn": 2}}', 1283063753000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p784507-ce101', 'stk-a7md_i', 'CE 101', 'info', '{"desc": "بالنسبة للدكتور باشامه يعطي واجب رسمة اسبوعيا وتصحيحه في المياجر شوي شديد لكن الدكتور صارلي معاه موقف وكبر في عيني الله يجزاه خير\n\nبالنسبة للمادة اذا كنت ترى الأوتوكاد حق الأوريا سهل فالمادة رح تكون سهلة بالنسبة لك واذا كنت تشوفه صعب رح تكون صعبه\n\nانا بالنسبة لي كانت المادة سهلة جدا لكن كان معانا في الاب طلاب مفحطين فما أقدر أحكم\n\nنصيحتي نزل المادة وشوف أول إسبوعين إذا شفت الأمور ماشيه كمل لأن المستوى لن يزداد صعوبة بشكل كبير وإذا شفت الوضع صعب إحذف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-101/102249/6", "user": "a7md_i", "ts": 1297208137000, "tid": 102249, "pn": 6}}', 1297208137000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p462722-ce101', 'stk-user3193', 'CE 101', 'info', '{"desc": "ال 103\n\nراح تدرس برمجة السي بلس\n\nعندك كلاسين بالاسبوع مع لاب واحد بالاسبوع مدري هو 4 او 3 ساعات ناسي والله\nوالهوموركات تقريبا اقل من ال ce ولكن في اخر السمستر يطلبون منك مشروع برنامج ويمكن ياخذ منك وقت\n\nوالمادة مترابطة بشكل كبير يعني متسلسله يعني كل ماتدرس شي راح يستمر معك للدرس الي بعده وكذا\n\nوالكوزات تقريبا 5 كوزات طول السمستر\n\nوالمادة سهله اذا ركزت فيها من البداية واشتغلت صح ويبغى لها جهد\n\nاما ال 101\n\nمادة تتكلم عن برنامج الاوتوكاد ( الرسم الهندسي ) مثل الي درستوه في الورك شوب لكن راح تتوسع زياده\nوالمادة يبغى لها بس بعد نظر يعني اذا عندك تخيل كويس بتبدع فيها والمادة اسهل من ics\nولكن هوموركاتها اكثر تقريبا كل كلاس هومورك ولكن سهل وطبعا ماراح تبدع الا اذا حليت الهوموركات وفهمتها صح\nوالمادة لاب واحد اسبوعيا مدته 4 ساعات\nوالكوزات انا نزلتها بالصيف ولاكوز اخذته ولكن المادة سهله واهم شي لاتغيب ولا كلاس فيها\n\nمن وجهة نظري جدولك يناسب لك ال ce 101 وبالتوفيق يالغلا\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce101-or-ics103/77781/2", "user": "user3193", "ts": 1253614564000, "tid": 77781, "pn": 2}}', 1253614564000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p532361-ce101', 'stk-user1939', 'CE 101', 'info', '{"desc": "المادة سهلة جدا خاصة اذا اخذتها مع المانع\n\nشكري سنان سييييييء ما انصحك تاخذ معه\n\nخذها مع المانع وتوكل على الله وانتبه معه بالشرح زيييين وحاول تحل الرسمات اللي باللاب وانت فاهم موب تنقلها نقل عشان ترتاح بالمياجر … وايضا نفس الشي لرسمات الهوموورك\n\nوقبل المياجر تمرن على رسمات اللاب والهووموورك عشان تجيب قريد\n\nوخلها عندك على فلاش دايمن\n\nبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-101/82847/2", "user": "user1939", "ts": 1264887970000, "tid": 82847, "pn": 2}}', 1264887970000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p47019-ce101', 'stk-_who_knows', 'CE 101', 'info', '{"desc": "1- **SE 205 **: دفوعة ( DUFFUAA ) أو درويش ( DARWESH ) …\n\n2- CE 101 : المانع ( AL-MANA ) …\n\n3- ME-215 : من وجهة نظري أن علام ( ALLAM ) ممتاز لأني درست عنده مع ملاحظة ان ما عنده نوته … هو يشرح و انت تسجل اي ملاحظة تشوف انها مهمة في الكتاب وأعط المادة حقها من الدراسة وصدقني تطلع معه بقريد ممتاز … العيب الوحيد زي ماقال الاخ SKFUPM A ان الاختبارات طوييييلة … يعني ممكن تطفش وانت تحل … اما خان ما اعرف عنه ممكن يفيدونك الشباب …\n\nولك تحياتي …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/32979/11", "user": "_who_knows", "ts": 1081424064000, "tid": 32979, "pn": 11}}', 1081424064000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1462814-ce101', 'stk-user8581', 'CE 101', 'info', '{"desc": "ما عندي فكرة عن CE 101 إن شاء الله شباب الاندستريال يفيدونك\nلكن مادام بتنزل صيف فالأفضل\nفي 162 تنزل كيسمتري 101 في 162 + انجلش 102\nوفزكس 102 في الصيف مع الانجلش 214 او كورس GS او تنزل فزكس 102 + انجلش 102\n\n- خطأ انك بس تنزل انجلش في الصيف خل معاه كورس صعب او متوسط .\n- أهم شيئ لاتنزل كيمستري في الصيف لو يصير الي يصير لأن الأفرج عال عكس الفزكس 102 فالقريدات ستنادرد .\nالشيئ الثاني نصيحة لا تأخر شيئ من الفريشمان للسفمور او من السفمور للجونير لأنك مثلا لو أجلت الكيميستري للسفمور راح تكون مشغول بمواد التخصص أكثر و الكيسمتري راح تزعجك .\nفرايي خلص كل كورسات الفريشمان في الفريشمان وامش على الخطة الي قلتها لك .\n+\nهذا قروب الاندستريال في الفيسبوك وهم ماراح يقصروا … سجل في القروب وإن شاءالله راح اضيفك .\nhttps://www.facebook.com/groups/KFUPMISE/\n\nالله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/175357/2", "user": "user8581", "ts": 1479840336000, "tid": 175357, "pn": 2}}', 1479840336000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p607793-ce101', 'stk-user5216', 'CE 101', 'info', '{"desc": "مشالله جدولك كويس بس نزل الانقلش بالصيف افضل\n\nوخلي جدولك كذا\n\n093\nماث 201 و انجلش 102\n\n101\nماث260 و فيزكس 102 و عربي 101 و ics 103 و ce 101\n\nشوف يالغلا قبل لا اتفلسف عليك بقولك اني زيك لسه مااخذت ماث 201\nلكن هذي بعض اراء الاخوان بحثت عنها في المنتدى\nلاني بنزلها بالصيف 😏\n\nوعليكم السلام\nانا عندي الان ماث 201 وباقي ماخذت الانقلش 214 بس اللي اعرفو انو هذا الكورس غثيث مرة وماث 201 اللي يقول اسهل من 102 لاتصدقوا الكورس يبغالو شغل فما انصحك خذ واحد منهم مع اسلامي او عربي والسؤال الثاني تقدر ليش لا\n\nhttp://skfupm.com/vb/showpost.php?p=577593&postcount=2\n\nأنا الصيف اللي فات أخذت انقلش 102 وماث 201\nوالله العظيم ونسه وتحس نفسك فاااااضي أصلاا\nمافي الا الماث تذاكره وهو أسهل كورس في كورسات المااث جميعااا\n\nتوكل على الله وسويها\n\nhttp://skfupm.com/vb/showpost.php?p=577910&postcount=5\n\nالخلاصه اذا كان مستواك بالماث كويس فراح ترفع لك معدلك …\nوماهي غثيثة زي 102 بكل الاحوال\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88232/2", "user": "user5216", "ts": 1273981968000, "tid": 88232, "pn": 2}}', 1273981968000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1071008-ce101', 'stk-metallic', 'CE 101', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته …\n\nبالنسبة للـ 210 فلا يمكن معادلتها أبداً بـ ce 101 ياخي البرنامج نفسه يختلف … وبعدين المادة حلوة وممتعة … عموماً أنت ملزوم تأخذها …\n\nبالنسبة للـ 322 ولابها، تراها تختلف اختلاف كبير عن 216 ، ونسبة الترابط بينهم صغيرة جداً … وال322 أسهل بمراحل من الـ 216 …\n\nمن النقاط أعلاه 🤠 ، أنا أقول أنك تبدل الـ210 بالـ322 أفضل، لأن جدولك صعب في نظري …\n\nموفق … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/113-121/123597/556", "user": "METALLIC", "ts": 1343047528000, "tid": 123597, "pn": 556}}', 1343047528000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng.3booodii-ce101', 'stk-eng.3booodii', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f98566", "n": "Dr. Saleh Abdulla Almana", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce101-101\n\nالتحضير : يحضر بداية اللاب وما يحب التأخير …\n\nطريقة الشرح : يشرح الدرس كامل ويرسم لنا رسمة من الكلاس وورك\n\nالمياجر: أصعب من الهوموركات والكلاسوورك بشي بسيط … يعني يكون فيها تريك بسيط عشان بس يفرق بين الطلاب\n\nالفاينال : نفس المياجر\n\nالقريد النهائي: A+\n\nإضافات : المادة ستاندرد … لكن إلي يجيب 83 يدفه للقريد إلي بعده وهكذا\n\nبالنسبة لي مدرس ممتاز … الله يحفظه ويوفقه … صاحب إبتسامه وأخلاق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p852222-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-saleh-abdulla-almana/98566/5", "user": "eng.3boOodii", "ts": 1307961820000, "tid": 98566, "pn": 5}}]}', 1307961820000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sub_ze_0_ro-ce101', 'stk-sub_ze_0_ro', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f98574", "n": "Dr. Mostefa Bouchama", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 101\n\nمايشرح بس يطبق على الشاشه وانت تشوف وتتعلم…اغبى طريقه شفتها …\n\nصراحه اتمنى لو اني مانزلت معاه…\n\nلان مياجره مو على قد شرحه…\n\nيجيب مياجر صعبه جدا على طلاب مالهم خبرهـ…\n\nهذا رايي فيه…ولاانصح اي احد ينزل معآهـ…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970537-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mostefa-bouchama/98574/9", "user": "sub_ze_0_ro", "ts": 1326899328000, "tid": 98574, "pn": 9}}]}', 1326899328000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-ce101', 'stk-mkd', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f98574", "n": "Dr. Mostefa Bouchama", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 101\nTerm 161\n\nالتحضير : يركز على التحضير وممكن يهزأك لو جيت متاخر\nطريقة الشرح : مقبولة . نظامه يتوقع من الطالب يلقط المعلومو على الطاير ويفهمها على طول ( يحب الطالب يكتب نوتات معه بالكلاس )\nالمياجر: أصعب من الكلاس وورك حبتين ، لو فهمت الكلاسوررك صح 100% إن شاء الله ما يصير الميجر صعب عليك\nالفاينلات : زي المياجر . الميجرين عليهم 30 والفاينل 20 - كلاسوررك 40 و هوموورك 10\nالصوت: واضح ، الأكسنت مب أسطورية بس بتفهم عليه إن شاء الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466723-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mostefa-bouchama/98574/23", "user": "MKD", "ts": 1485019627000, "tid": 98574, "pn": 23}}]}', 1485019627000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-azzubair-ce101', 'stk-azzubair', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f98574", "n": "Dr. Mostefa Bouchama", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 101 term 161\n\nشرحه كويس ويوريك مثال على الرسمة اللي بتاخذها وبعدين يعطيك رسمة او اثنين للكلاس وورك ووحدة هوم وورك\nمياجره الاول كان صعب والثاني كان سهل لكن بشكل عام تعتبر سهلة ويعطيك رسمتين في كل ميجر\nالفاينل يختبرك في المواضيع اللي ما دخلت في الميجر 1 ولا الميجر 2 وكان سهل نوعا ما\nما يحب التاأخير كثير ويبيك تشتغل في اللاب\nالمدرس متعاون شوي واشوفه افضل من بيق ويعطي بونص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467650-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mostefa-bouchama/98574/24", "user": "azzubair", "ts": 1486289345000, "tid": 98574, "pn": 24}}]}', 1486289345000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_3abed1-ce101', 'stk-abu_3abed1', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f98574", "n": "Dr. Mostefa Bouchama", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 101 - TERM 182\n\nالتحضير: بشكل دائم وما يتساهل مع التأخير.\n\nالشرح : في البداية يشرح الدرس على السبورة و يوضح اهم النقاط برسم يدوي ، كان يعطيك صورة عامة عن الدرس وبعدها( وهنا اهم جزء) كان يفتح البروجكتور و يطبق اللي شرحه في السبورة على الكمبيوتر ( برنامج الاوتوكاد اللي اخذناه في السنة التحضيرية) ولكن عيبه الله يهديه انه احيانا يكون سريع شوي في التطبيق فتضيع في وحده من الخطوات وبالتالي تضيع في البقية ومن ايجابياته في الشرح انه ممكن يعيد الشرح من بدايته اذا شافنا مو فاهمين او يشرح جزئية معينه اذا احد رفع ايده وقال للدكتور انه ما فهمها.\n\nوبعدها يوزع علينا رسمتين ( وحده كلاس وورك تسويها وتسلمها و اول ما تخلصها تتوكل على بيتكم وطبعا يساعدك فيها اذا مش فاهم، والثانية هومورك وتجيبها الاسبوع القادم)\n\nالمياجر والفاينلات : عبارة عن رسمتين كل وحده متعلقة بموضوع اخذته من قبل ، واذا كنت فاهم كل الكلاس وورك وحليت بنفسك كل الهوموركات ففالك الفل في المياجر والفاينل ان شاء الله لانهم ما يطلعون عن الافكار اللي اخذتها مسبقا .\n\nالصوت : واضح ولغة انجليزية مفهومة وواضحه ( بأكسنت جزائري احيانا).\n\nالتقييم النهائي : اعطيه 8\\10\n\nاضافات:\n- كان يقهرني الله يسامحه بطريقة تصحيحه اللي اعتبره مجحف ، ولو يعدل تصحيحه يطلع اسطورة المادة هذه مقارنة بغيره.\n- الكثير من الشباب يمدحونه ويفضلونه عن BAIG من ناحية الشرح والقريدات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510119-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mostefa-bouchama/98574/27", "user": "Abu_3abed1", "ts": 1558663230000, "tid": 98574, "pn": 27}}]}', 1558663230000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed095-ce101', 'stk-mohammed095', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f98580", "n": "Dr. Mirza Ghouse Baig", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce101-142\n\nالتحضير : يومياً بداية الكلاس\n\nطريقة الشرح : يبدأ يشرح الدرس والكونسبت لمدة ساعة تقريباً بعدين يطبق واحده من رسمات الكلاس ورك\n\nالكويزات : مافيه\n\nالهومورك : اسبوعياً يعطيك رسمة أو رسمتين نفس فكرة الكلاس ورك.\n\nالمياجر: الميجر الأول كان مستواه متوسط والافرج تقريباٌ 80% ، بس الميجر الثاني كان صعب شوي وغالبا لان الماتيريال حقت الميجر الثاني اصعب وفيها أفكار اعقد الافرج كان 65% على كلام الشباب تغير النظام في 151 وصار ميدتيرم ]\n\nالفاينلات : متوسط مائل للصعوبة ، لكن كان متعاون في التصحيح\n\nالقريد النهائي: A\n\nالصوت: واضح ، واكسنت كويس\n\nإضافات : الدكتور متعاون جداً مع الطلاب ، جيت كذا مره في الوفيس اور عشان الهومورك وكان يقولي وين الاخطاء في الحل ويساعد في الفكرة.\n+ المادة يبغاله تخيل شوي + براكتس ، اذا حليت الكلاس وررك والهومورك بنفسك راح تكون فاهم بشكل كبير وماتحتاج إلا مراجعة بسيطة قبل الأختبار.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446271-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mirza-ghouse-baig/98580/18", "user": "Mohammed095", "ts": 1460291141000, "tid": 98580, "pn": 18}}]}', 1460291141000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulmalik123-ce101', 'stk-abdulmalik123', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f98580", "n": "Dr. Mirza Ghouse Baig", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE101-192\n\nالتحضير : يتاخر دايماً حول ال٥ دقايق والتحضير يكون بعد المقدمة لو جيت بعد التحضير بيحطك تاخير بس ما افتكر قد غيب احد حضر متاخر.\n\nطريقة الشرح : يبدأ يشرح الدرس والكونسبت وبعدها يبدأ يطبق الشي الي اخذناه.\n\nالكويزات : مافي\n\nالهومورك : اسبوعياً يعطيك رسمة أو رسمتين اصعب من الكلاس وورك بشويات بس لو سويتها بتكون فاهم.\n\nالمياجر: المادة اتغير نظامها وسارت ميدتيرم عليه ٢٥٪؜ و الفاينل عليه ٣٥٪؜. الميد حقه كان صلخ شويتين فيه افكار غريبة لكن معقول للي فاهم ومذاكر. والافرج حقه كان ١٧ من ٢٥\n\nالفاينلات : اتكنسل بسبب كورونا\n\nالقريد النهائي: +B\n\nالصوت: واضح ، والاكنست كويس\n\nإضافات : الدكتور متعاون مع الطلاب يأجل الهوموورك في ايام المياجر و شرحة ممتاز لو ركزت معاه بتفهم كويس. المادة نظامها تدريب بحت يعني لو ما سويت الكلاس وورك والهوموورك بنفسك بتتعب شويتين فانتبه من ذا الموضوع. والمادة عيبها ما تعتمد على كمية مذاكرتك قد ما تعتمد على قوة تخيلك للشكل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521732-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mirza-ghouse-baig/98580/19", "user": "abdulmalik123", "ts": 1588510176000, "tid": 98580, "pn": 19}}]}', 1588510176000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ce101', 'stk-bader_alqahtani', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f183561", "n": "Dr. Ahmed Shareef", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE101-Term 201\nالتحضير :بداية السمستر كان التحضير يكون من البلاك بورد و كان تعامله راقي جدا الين جا اخر السمستر و يبدا يسال بشكل عشوائي و يقول لطلاب كملوا معي او وش اسوي الحين حرفيا كام مستفز\nطريقة الشرح :شرح عادي يفهم بس مرات يستخدم طرق صعبة و كان يمديه يسهلها على نفسه و علينا و اشوفه اقل من عادي مو قد المدح حق الطلاب\nالكويزات :المادة ما فيها كوزات بس في ترمنا الوضع استثنائي كان ماسك ثلاث شعب و اول وحدة جابلهم كوز صعب و الثاني وسط و الاخير شي تافه الي هي شعبتنا\nالمياجر:ما فيه مياجر فيه مد و جاب مد صعب ولا قد شرحه ولا الواجب او الكلاس ورك و كل شعبة لها مد مختلف شفت حقين الاحد و الاثنين اسهل من الاربعاء\nالفاينلات :الفاينال كان كومون و الي كتبه بيق و كان اسهل من المد\nالقريد النهائي:الصراحة اعطيه C\nالصوت:الصوت عادي\nإضافات :التصحيح يبالغ فيه في الكلاس ورك و الهومورك و مرة يدقق عالي ياخذون من اخوياهم اذا قفطك بيعطيك ٥/١٠ ذي تحسب له انه ما يعطي ٠ الملخص تصحيح سيء في المد و الفاينال و كل شي\nما انصح فيه صراحة حرفيا كان تعامله معنا كويس لاكن مرات تجيه فصلات يكون مستفز و زلع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1528893-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-shareef/183561/2", "user": "Bader_Alqahtani", "ts": 1614979469000, "tid": 183561, "pn": 2}}]}', 1614979469000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dex-ce101', 'stk-dex', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f183561", "n": "Dr. Ahmed Shareef", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE101 - Term211\nالتحضير :\nكان قروبين واحد حضوري وواحد اونلاين … الحضوري كان ياخذه من تسليم الكلاس وورك وولا يحاسب على التأخير اما الاونلاين كان ينادي بالاسماء\nطريقة الشرح :\nيسوي الكلاس وورك كامل خطوه بخطوه واضح جداً واي نقطه ما تفهمها عادي تقاطعه وتسأله … يعني لو تتابع معه بتاخذ فل بكل كلاس وورك\nالكويزات :\nكويزين اول واحد كان جداً بسيط … الثاني كان خيارات شوي صعب … كل كويز من ٥\nالمياجر:\nوسط\nالفاينلات :\nصصصصععععبببب\nالقريد النهائي:\nB\nالصوت:\nواضح\nإضافات :\nالدكتور شوي يستقعد بالتصحيح خاصه اذا سلمت بدري … انصح ببيق اكثر رغم ان شرح الشريف افضل لكن محاضراته كلها موجوده ومسجله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533346-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-shareef/183561/3", "user": "Dex", "ts": 1641560381000, "tid": 183561, "pn": 3}}]}', 1641560381000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-ce101', 'stk-user12137', 'CE 101', 'doc', '{"docs": [{"id": "stk-dr-f183561", "n": "Dr. Ahmed Shareef", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE101-T222\n\nالتحضير : يأخذ التحضير بعد 10 دقائق من بدأ الكلاس ويمشي المتأخرين, وفي رمضان قلل وقت كلاساتنا مراعاة لتعب الصيام\n\nطريقة الشرح : شرحه ممتاز وسلس, يسوي الكلاس وورك قدامك كامل خطوة بخطوة ويشرح كل تحريكة للفأرة ما شاء الله عليه بشكل واضح جداً واي نقطه ما تفهمها عادي تقاطعه وتسأله … يعني لو تتابع معه بتأخذ فل بكل كلاس وورك وعنده مقاطع مسجلة في حال ما فهمت او غبت او سرحت\n\nالكويزات : سهلة جدا, الاول ما يحتاج مذاكرة بس الثاني يبغاله مراجعة أمانة عشان تجيب درجة جيدة\n\nالميد: أظن الديبارتمنت االي يسويها ومستواه وسط\n\nالفاينلات : ايضا اعتقد الديبارتمنت الي يسويه ومستواه صعب شوي\n\nالقريد النهائي: A+\n\nالصوت: هندي هو لكن لهجته واضحة والصوت واضح ويوصل لبعيد وأحيانا يستعمل مكبر صوت\n\nإضافات :\n-الدكتور خلوق ومحترم ومتساعد جدا في شرحه وحريص على فهم كل الطلاب, وكان يمشي الطلاب اذا تأخروا عن تسليم الواجب عن الديدلاين ولو بعد مدة طويلة\n-من ناحية تصحيح واالله مادري بالنسبة لي حسيته عادل ما أحس زبطني ولا حسيته ظلمني\n-أعتقد الي فوقي مبالغين بقوة في التسفيل في الدكتور\n-الي اعرفه ان شرح الشريف افضل وتصحيح عمران في تزبيط أكثر (فشوف وش تبغى أنت) أنا طلعت بB+ وهذا أنا ساحب على بعض الهووموركات ومسلم بعضهم وانا متأكد انهم غلط ومخبص في الفاينل؛ فلا تخاف اذا اخذته اقلها B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536922-ce101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-shareef/183561/5", "user": "user12137", "ts": 1693318324000, "tid": 183561, "pn": 5}}]}', 1693318324000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
